#!/bin/sh
# Generated by tungo-sdkgen. Do not edit.
#
# Installs the packed Tungo.Sdk from a local folder into a clean console project and runs it:
#
#   dotnet pack -c Release -o artifacts
#   sh scripts/package-smoke.sh artifacts
set -eu

artifacts="$(cd "${1:-artifacts}" && pwd)"
package="$(ls "${artifacts}"/Tungo.Sdk.*.nupkg | head -n 1)"
version="$(basename "${package}" .nupkg)"
version="${version#Tungo.Sdk.}"

work="$(mktemp -d)"
trap 'rm -rf "${work}"' EXIT
cd "${work}"

# A private package folder and the local folder as the only source: neither a cached copy nor a
# published package of the same version can stand in for the one that was just built.
export NUGET_PACKAGES="${work}/packages"
cat > nuget.config <<EOF
<?xml version="1.0" encoding="utf-8"?>
<configuration>
  <packageSources>
    <clear />
    <add key="local" value="${artifacts}" />
  </packageSources>
</configuration>
EOF
cat > Smoke.csproj <<EOF
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net\$(BundledNETCoreAppTargetFrameworkVersion)</TargetFramework>
    <Nullable>enable</Nullable>
    <ImplicitUsings>enable</ImplicitUsings>
    <TreatWarningsAsErrors>true</TreatWarningsAsErrors>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="Tungo.Sdk" Version="${version}" />
  </ItemGroup>
</Project>
EOF
cat > Program.cs <<'EOF'
using Tungo.Sdk;

using var client = new TungoClient(new TungoClientOptions { ApiKey = "tg_smoke", CompanyId = "co_smoke" });
Console.WriteLine("Tungo.Sdk " + TungoSdkInfo.Version + " " + client.BaseUrl + " " + TungoMoney.ToTiyn("1.005"));
EOF

output="$(dotnet run -c Release)"
echo "${output}"
case "${output}" in
  "Tungo.Sdk ${version} https://"*" 101") ;;
  *)
    echo "error: the installed package did not behave as expected" >&2
    exit 1
    ;;
esac
